import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

/* ================= FALLBACK IMAGE ================= */
const FALLBACK_IMAGE =
  "https://images.unsplash.com/photo-1517836357463-d25dfeac3438";

/* ================= PROGRAM DATA ================= */
const programs = [
  {
    title: "Weight Training",
    img: "https://images.unsplash.com/photo-1517836357463-d25dfeac3438",
    short:
      "Structured strength training focused on form, progression, and consistency.",
    branches: {
      "Nava India": {
        img: "https://images.unsplash.com/photo-1599058917212-d750089bc07e",
        text:
          "Advanced free-weight training with compound lifts, progressive overload, and expert supervision for long-term strength development.",
      },
      "RS Puram": {
        img: "https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b",
        text:
          "Machine-based and beginner-friendly strength programs focused on safety, posture, and gradual progression.",
      },
      Kovaipudur: {
        img: "https://images.unsplash.com/photo-1550345332-09e3ac987658",
        text:
          "Functional strength routines emphasising stability, balance, and injury prevention for daily movement efficiency.",
      },
    },
  },
  {
    title: "Cardio Fitness",
    img: "https://images.unsplash.com/photo-1599058917212-d750089bc07e",
    short: "Planned cardio workouts designed to build endurance and stamina.",
    branches: {
      "Nava India": {
        img: "https://images.unsplash.com/photo-1546484959-f2c0f0b77b23",
        text:
          "High-intensity cardio circuits using treadmills, assault bikes, and rowing machines for maximum calorie burn.",
      },
      "RS Puram": {
        img: "https://images.unsplash.com/photo-1538805060514-97d9cc17730c",
        text:
          "Steady-state endurance training designed for heart health, fat loss, and stamina improvement.",
      },
      Kovaipudur: {
        img: "https://images.unsplash.com/photo-1579758629938-03607ccdbaba",
        text:
          "Low-impact cardio sessions suitable for beginners and recovery-focused members.",
      },
    },
  },
  {
    title: "Personal Training",
    img: "https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b",
    short: "One-on-one coaching tailored to individual fitness goals.",
    branches: {
      "Nava India": {
        img: "https://images.unsplash.com/photo-1594381898411-846e7d193883",
        text:
          "Elite personal coaching with customised workout plans, nutrition guidance, and detailed progress tracking.",
      },
      "RS Puram": {
        img: "https://images.unsplash.com/photo-1517960413843-0aee8e2b3285",
        text:
          "Goal-oriented personal training focused on fat loss, strength building, and sustainable lifestyle balance.",
      },
      Kovaipudur: {
        img: "https://images.unsplash.com/photo-1558611848-73f7eb4001a1",
        text:
          "Beginner-friendly personal training with movement correction, confidence building, and guided progression.",
      },
    },
  },
  {
    title: "Zumba",
    img: "https://images.unsplash.com/photo-1549576490-b0b4831ef60a",
    short: "Dance-based cardio sessions focused on rhythm and endurance.",
    branches: {
      "Nava India": {
        img: "https://images.unsplash.com/photo-1524594152303-9fd13543fe6e",
        text:
          "High-energy Zumba sessions combining rhythm, choreography, and cardio for fun, calorie-burning workouts.",
      },
    },
  },
  {
    title: "Group Training",
    img: "https://images.unsplash.com/photo-1518611012118-696072aa579a",
    short: "Coach-led group workouts designed for motivation and consistency.",
    branches: {
      "Nava India": {
        img: "https://images.unsplash.com/photo-1534438327276-14e5300c3a48",
        text:
          "Structured group workouts blending strength and conditioning to boost motivation and accountability.",
      },
    },
  },
  {
    title: "Functional Training",
    img: "https://images.unsplash.com/photo-1550345332-09e3ac987658",
    short: "Movement-based training to improve strength, balance, and mobility.",
    branches: {
      "Nava India": {
        img: "https://images.unsplash.com/photo-1605296867304-46d5465a13f1",
        text:
          "Mobility-driven functional workouts using kettlebells, resistance bands, and bodyweight movements.",
      },
      "RS Puram": {
        img: "https://images.unsplash.com/photo-1554298128-c916518a4f60",
        text:
          "Functional routines aimed at improving posture, balance, and daily movement efficiency.",
      },
    },
  },
  {
    title: "HIIT Training",
    img: "https://images.unsplash.com/photo-1599058918144-1ffabb6ab9a0",
    short: "High-intensity interval training for fat loss and endurance.",
    branches: {
      "Nava India": {
        img: "https://images.unsplash.com/photo-1594737625785-cb06d78d0b53",
        text:
          "Explosive HIIT sessions combining strength and cardio for maximum fat burn in minimal time.",
      },
    },
  },
];

/* ================= COMPONENT ================= */
export default function Programs() {
  const [active, setActive] = useState(null);
  const [showAll, setShowAll] = useState(false);

  const visiblePrograms = showAll ? programs : programs.slice(0, 6);

  return (
    <section id="programs" className="bg-black text-white py-32 px-6 scroll-mt-28">
      <div className="max-w-7xl mx-auto">

        {/* HEADING */}
        <div className="text-center max-w-3xl mx-auto mb-20">
          <h2 className="text-4xl md:text-5xl font-bold">
            Our <span className="text-[#e9b21a]">Programs</span>
          </h2>
          <p className="mt-6 text-gray-400">
            Structured programs designed to support every fitness goal.
          </p>
        </div>

        {/* PROGRAM GRID */}
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-10">
          {visiblePrograms.map((p, i) => (
            <motion.div
              key={i}
              whileHover={{ y: -8 }}
              transition={{ duration: 0.3 }}
              className="rounded-2xl overflow-hidden border border-white/10 bg-black shadow-xl"
            >
              <img
                src={p.img}
                onError={(e) => (e.currentTarget.src = FALLBACK_IMAGE)}
                alt={p.title}
                className="h-56 w-full object-cover"
              />

              <div className="p-6 flex flex-col h-[230px]">
                <h3 className="text-xl font-semibold">{p.title}</h3>
                <p className="mt-3 text-sm text-gray-400 flex-1">
                  {p.short}
                </p>

                {/* OLD PREMIUM BUTTON STYLE */}
                <button
                  onClick={() => setActive(p)}
                  className="mt-5 w-fit px-6 py-2 rounded-full border border-[#e9b21a] text-[#e9b21a] hover:bg-[#e9b21a] hover:text-black transition"
                >
                  View Details
                </button>
              </div>
            </motion.div>
          ))}
        </div>

        {/* VIEW MORE / LESS */}
        {programs.length > 6 && (
          <div className="text-center mt-16">
            <button
              onClick={() => setShowAll(!showAll)}
              className="px-8 py-3 rounded-full bg-[#e9b21a] text-black font-semibold hover:bg-[#d4a318] transition"
            >
              {showAll ? "View Less" : "View More Programs"}
            </button>
          </div>
        )}
      </div>

      {/* ================= DETAILS OVERLAY ================= */}
      <AnimatePresence>
        {active && (
          <motion.div
            className="fixed inset-0 z-50 bg-black/90 backdrop-blur-xl overflow-y-auto px-6 py-20"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <div className="max-w-6xl mx-auto">
              <button
                onClick={() => setActive(null)}
                className="mb-10 text-gray-400 hover:text-white"
              >
                ← Back to Programs
              </button>

              <h3 className="text-4xl font-bold mb-12">
                {active.title}
              </h3>

              {/* RESPONSIVE BRANCH GRID */}
              <div
                className={`grid gap-8 ${
                  Object.keys(active.branches).length === 1
                    ? "grid-cols-1"
                    : Object.keys(active.branches).length === 2
                    ? "md:grid-cols-2"
                    : "md:grid-cols-2 lg:grid-cols-3"
                }`}
              >
                {Object.entries(active.branches).map(([name, data], i) => (
                  <motion.div
                    key={name}
                    initial={{ opacity: 0, y: 40 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.15 }}
                    className="rounded-2xl overflow-hidden border border-white/10 bg-black"
                  >
                    <img
                      src={data.img}
                      onError={(e) =>
                        (e.currentTarget.src = FALLBACK_IMAGE)
                      }
                      alt={name}
                      className="h-56 w-full object-cover"
                    />
                    <div className="p-6">
                      <h4 className="text-xl font-semibold mb-3 text-[#e9b21a]">
                        {name}
                      </h4>
                      <p className="text-sm text-gray-400 leading-relaxed">
                        {data.text}
                      </p>
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
}
